import{bQ as a,aL as e,u as i,G as l}from"./chunks/framework.DaEK0KQB.js";const g=JSON.parse('{"title":"内网高德地图代理问题","description":"","frontmatter":{"title":"内网高德地图代理问题","date":"2026-05-19T11:35:08.000Z","permalink":"/pages/f10889/","categories":["更多","实用技巧"],"tags":[null]},"headers":[],"relativePath":"更多/实用技巧/13.内网高德地图代理问题.md","filePath":"更多/实用技巧/13.内网高德地图代理问题.md","lastUpdated":1786944735000}'),s={name:"更多/实用技巧/13.内网高德地图代理问题.md"};function r(n,t,o,h,d,p){return e(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="内网高德地图代理问题" tabindex="-1">内网高德地图代理问题 <a class="header-anchor" href="#内网高德地图代理问题" aria-label="Permalink to &quot;内网高德地图代理问题&quot;">​</a></h1><p>内网离线可用｜高德地图私有化部署两种代理方案实战对比（Node反向代理 + ServiceWorker拦截）</p><h2 id="一、前言-内网地图痛点" tabindex="-1">一、前言：内网地图痛点 <a class="header-anchor" href="#一、前言-内网地图痛点" aria-label="Permalink to &quot;一、前言：内网地图痛点&quot;">​</a></h2><p>在政务、园区、工厂、军工等<strong>严格内网隔离</strong>的项目中，前端项目无法直接访问外网高德域名：</p><ul><li><code>webapi.amap.com</code></li><li><code>jsapi-data1.amap.com</code></li><li><code>webst01.is.autonavi.com</code>（卫星瓦片）</li></ul><p>浏览器直接加载高德SDK会出现：<strong>跨域、混合内容、外网拦截、地图白屏、瓦片加载失败</strong>。</p><p>高德官方并未提供私有化离线部署包，因此行业通用解决方案只有两种：</p><ol><li><strong>后端代理</strong>：Node + Express 中转请求、批量替换域名（本人开源实现）</li><li><strong>前端拦截</strong>：Service Worker 劫持浏览器请求，本地改写域名</li></ol><p>本文结合真实踩坑经验，深度对比两套方案，附带开源代码、原理、优缺点、适用场景。</p><blockquote><p><strong>开源仓库</strong>：<a href="https://github.com/akcshen/gaode-proxy.git" target="_blank" rel="noreferrer">https://github.com/akcshen/gaode-proxy.git</a></p><p><strong>技术栈</strong>：Node.js + Express + Axios、响应流批量替换、二进制透传</p></blockquote><h2 id="二、方案一-node-express-后端反向代理-生产主推" tabindex="-1">二、方案一：Node+Express 后端反向代理（生产主推） <a class="header-anchor" href="#二、方案一-node-express-后端反向代理-生产主推" aria-label="Permalink to &quot;二、方案一：Node+Express 后端反向代理（生产主推）&quot;">​</a></h2><h3 id="_2-1-方案原理" tabindex="-1">2.1 方案原理 <a class="header-anchor" href="#_2-1-方案原理" aria-label="Permalink to &quot;2.1 方案原理&quot;">​</a></h3><p>搭建一台内网 Node 代理服务，浏览器<strong>只访问内网代理地址</strong>，由服务端向外网请求高德资源，并且对返回内容做<strong>全局域名替换</strong>。</p><p>核心流程：</p><ol><li>前端引入 <code>http://内网ip:3000/amapproxy/maps</code> 加载SDK；</li><li>Node 服务请求官方高德SDK；</li><li>对 JS、JSON、文本类响应<strong>批量替换域名</strong>为内网代理地址；</li><li>对 PBF、PNG 瓦片二进制资源<strong>原样透传</strong>，不做编码转换；</li><li>浏览器拿到改写后的SDK，后续瓦片、接口全部走内网代理。</li></ol><h3 id="_2-2-核心能力-开源项目能力" tabindex="-1">2.2 核心能力（开源项目能力） <a class="header-anchor" href="#_2-2-核心能力-开源项目能力" aria-label="Permalink to &quot;2.2 核心能力（开源项目能力）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">SDK入口代理</td><td style="text-align:left;"><code>/amapproxy/maps</code> 代理高德 JS SDK</td></tr><tr><td style="text-align:left;">Loca可视化代理</td><td style="text-align:left;">支持 Loca 三维SDK转发</td></tr><tr><td style="text-align:left;">通用资源转发</td><td style="text-align:left;">自动转发各类 amap.com 子域名</td></tr><tr><td style="text-align:left;">卫星瓦片代理</td><td style="text-align:left;">适配 <code>is.autonavi.com</code> 卫星、路网瓦片</td></tr><tr><td style="text-align:left;">智能内容改写</td><td style="text-align:left;">JS/JSON/URL 域名批量替换，二进制不处理</td></tr><tr><td style="text-align:left;">安全限制</td><td style="text-align:left;">限制合法子域名，防止开放代理滥用</td></tr></tbody></table><h3 id="_2-3-关键技术难点-本人真实踩坑" tabindex="-1">2.3 关键技术难点（本人真实踩坑） <a class="header-anchor" href="#_2-3-关键技术难点-本人真实踩坑" aria-label="Permalink to &quot;2.3 关键技术难点（本人真实踩坑）&quot;">​</a></h3><h4 id="难点1-https-域名嵌套改写困难" tabindex="-1">难点1：https 域名嵌套改写困难 <a class="header-anchor" href="#难点1-https-域名嵌套改写困难" aria-label="Permalink to &quot;难点1：https 域名嵌套改写困难&quot;">​</a></h4><p>高德SDK内部存在大量<strong>硬编码HTTPS域名、转义域名、模板域名</strong>：</p><ul><li>明文：<code>https://webapi.amap.com</code></li><li>转义：<code>https:\\/\\/webapi.amap.com</code></li><li>模板：<code>{webst01,webst02}.is.autonavi.com</code></li></ul><p>普通正则只能改明文，很多<strong>加密、分段、压缩后的HTTPS域名</strong>目前无法完全匹配，导致少量瓦片依然请求外网。</p><h4 id="难点2-二进制资源不能乱改" tabindex="-1">难点2：二进制资源不能乱改 <a class="header-anchor" href="#难点2-二进制资源不能乱改" aria-label="Permalink to &quot;难点2：二进制资源不能乱改&quot;">​</a></h4><p>瓦片图片、矢量PBF如果转成字符串替换，会直接损坏二进制编码，出现瓦片花屏、解析失败。</p><p><strong>解决方案</strong>：区分响应类型，<strong>文本类替换、二进制类直透</strong>。</p><h4 id="难点3-协议错乱-http-https混合" tabindex="-1">难点3：协议错乱（http/https混合） <a class="header-anchor" href="#难点3-协议错乱-http-https混合" aria-label="Permalink to &quot;难点3：协议错乱（http/https混合）&quot;">​</a></h4><p>内网是http，外网SDK写死https，改写不当会出现：</p><ul><li>混合内容报错</li><li>接口400/403</li><li>瓦片跨域</li></ul><p>项目提供 <code>PUBLIC_BASE</code>、<code>PUBLIC_SCHEME</code> 强制修正协议头。</p><h3 id="_2-4-优点-缺点" tabindex="-1">2.4 优点 &amp; 缺点 <a class="header-anchor" href="#_2-4-优点-缺点" aria-label="Permalink to &quot;2.4 优点 &amp; 缺点&quot;">​</a></h3><h4 id="✅-优点" tabindex="-1">✅ 优点 <a class="header-anchor" href="#✅-优点" aria-label="Permalink to &quot;✅ 优点&quot;">​</a></h4><ul><li><strong>前端零改动</strong>：代码不用改，只换SDK引入地址；</li><li><strong>兼容性最强</strong>：IE、老旧浏览器全部支持；</li><li><strong>统一管控</strong>：所有地图流量经过代理，方便防火墙管控；</li><li><strong>支持缓存</strong>：可加内存缓存/Nginx缓存，加速瓦片加载。</li></ul><h4 id="❌-缺点" tabindex="-1">❌ 缺点 <a class="header-anchor" href="#❌-缺点" aria-label="Permalink to &quot;❌ 缺点&quot;">​</a></h4><ul><li>存在少量<strong>深层加密HTTPS域名无法改写</strong>（目前遗留问题）；</li><li>需要额外部署一台Node服务；</li><li>高并发下性能弱于Nginx。</li></ul><h2 id="三、方案二-service-worker-前端请求拦截" tabindex="-1">三、方案二：Service Worker 前端请求拦截 <a class="header-anchor" href="#三、方案二-service-worker-前端请求拦截" aria-label="Permalink to &quot;三、方案二：Service Worker 前端请求拦截&quot;">​</a></h2><h3 id="_3-1-方案原理" tabindex="-1">3.1 方案原理 <a class="header-anchor" href="#_3-1-方案原理" aria-label="Permalink to &quot;3.1 方案原理&quot;">​</a></h3><p>不搭建后端服务，纯前端技术。利用浏览器 <strong>ServiceWorker（SW）</strong> 拦截当前页面所有网络请求。</p><p>流程：</p><ol><li>注册SW脚本，后台常驻；</li><li>监听所有 <code>fetch</code> 请求；</li><li>匹配高德域名，劫持请求；</li><li>改写请求Path、Header，转发到内网代理；</li><li>返回篡改后的响应给页面。</li></ol><h3 id="_3-2-优势" tabindex="-1">3.2 优势 <a class="header-anchor" href="#_3-2-优势" aria-label="Permalink to &quot;3.2 优势&quot;">​</a></h3><ul><li><strong>无需后端服务</strong>，纯前端实现；</li><li>拦截粒度更细，能拦截JS内部动态生成的请求；</li><li>不需要大量正则替换文本，直接拦截网络层；</li><li>完美解决深层加密HTTPS域名无法替换的问题。</li></ul><h3 id="_3-3-致命缺点-生产大坑" tabindex="-1">3.3 致命缺点（生产大坑） <a class="header-anchor" href="#_3-3-致命缺点-生产大坑" aria-label="Permalink to &quot;3.3 致命缺点（生产大坑）&quot;">​</a></h3><ul><li><strong>必须HTTPS环境</strong>：ServiceWorker 不允许纯http内网使用；</li><li><strong>不兼容老旧浏览器</strong>：IE彻底报废；</li><li>注册、更新、缓存机制诡异，经常拦截失效；</li><li>多标签页、刷新、离线状态容易BUG；</li><li>复杂SDK内部WebWorker发起的请求，SW拦截不到。</li></ul><h2 id="四、两套方案横向对比-总结干货" tabindex="-1">四、两套方案横向对比（总结干货） <a class="header-anchor" href="#四、两套方案横向对比-总结干货" aria-label="Permalink to &quot;四、两套方案横向对比（总结干货）&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">对比项</th><th style="text-align:left;">Node Express 代理</th><th style="text-align:left;">Service Worker 前端拦截</th></tr></thead><tbody><tr><td style="text-align:left;">部署难度</td><td style="text-align:left;">中等（部署Node服务）</td><td style="text-align:left;">简单（纯前端）</td></tr><tr><td style="text-align:left;">浏览器兼容性</td><td style="text-align:left;">极佳（兼容IE）</td><td style="text-align:left;">差（必须HTTPS、现代浏览器）</td></tr><tr><td style="text-align:left;">域名改写能力</td><td style="text-align:left;">大部分改写，少量加密HTTPS漏改</td><td style="text-align:left;">极强，网络层直接拦截</td></tr><tr><td style="text-align:left;">稳定性</td><td style="text-align:left;">高，适合长期生产</td><td style="text-align:left;">一般，缓存、刷新容易失效</td></tr><tr><td style="text-align:left;">运维成本</td><td style="text-align:left;">需维护Node进程</td><td style="text-align:left;">无需服务端</td></tr><tr><td style="text-align:left;">推荐场景</td><td style="text-align:left;">政务内网、老旧系统、生产环境</td><td style="text-align:left;">现代内网、仅测试、临时方案</td></tr></tbody></table><h2 id="五、目前最优落地组合方案" tabindex="-1">五、目前最优落地组合方案 <a class="header-anchor" href="#五、目前最优落地组合方案" aria-label="Permalink to &quot;五、目前最优落地组合方案&quot;">​</a></h2><p>结合我实际开发踩坑，<strong>生产环境推荐组合使用</strong>：</p><ol><li><strong>主方案</strong>：Node.js 代理服务（稳定、兼容、简单）；</li><li><strong>补充方案</strong>：少量漏改的HTTPS域名，用 ServiceWorker 兜底拦截；</li><li><strong>前置优化</strong>：外层套 Nginx 做负载、缓存、HTTPS证书终结。</li></ol><h2 id="六、开源项目使用教程" tabindex="-1">六、开源项目使用教程 <a class="header-anchor" href="#六、开源项目使用教程" aria-label="Permalink to &quot;六、开源项目使用教程&quot;">​</a></h2><p>仓库地址：<a href="https://github.com/akcshen/gaode-proxy.git" target="_blank" rel="noreferrer">https://github.com/akcshen/gaode-proxy.git</a></p><h3 id="_6-1-快速启动" tabindex="-1">6.1 快速启动 <a class="header-anchor" href="#_6-1-快速启动" aria-label="Permalink to &quot;6.1 快速启动&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_6-2-内网前端引入方式" tabindex="-1">6.2 内网前端引入方式 <a class="header-anchor" href="#_6-2-内网前端引入方式" aria-label="Permalink to &quot;6.2 内网前端引入方式&quot;">​</a></h3><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:3000/amapproxy/maps?v=2.0&amp;key=你的Key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_6-3-环境变量常用配置" tabindex="-1">6.3 环境变量常用配置 <a class="header-anchor" href="#_6-3-环境变量常用配置" aria-label="Permalink to &quot;6.3 环境变量常用配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUBLIC_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://192.168.x.x:3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ACCESS_LOG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="七、总结与后续优化方向" tabindex="-1">七、总结与后续优化方向 <a class="header-anchor" href="#七、总结与后续优化方向" aria-label="Permalink to &quot;七、总结与后续优化方向&quot;">​</a></h2><h3 id="_7-1-总结" tabindex="-1">7.1 总结 <a class="header-anchor" href="#_7-1-总结" aria-label="Permalink to &quot;7.1 总结&quot;">​</a></h3><p>高德内网代理没有完美方案，目前行业两种主流手段各有优劣：</p><ul><li><strong>Node反向代理</strong>：稳重、工程化、适合生产，唯一缺点是少量加密HTTPS域名无法改写；</li><li><strong>ServiceWorker</strong>：拦截强、不用部署服务，但是浏览器限制太多、稳定性差。</li></ul><h3 id="_7-2-后续优化计划" tabindex="-1">7.2 后续优化计划 <a class="header-anchor" href="#_7-2-后续优化计划" aria-label="Permalink to &quot;7.2 后续优化计划&quot;">​</a></h3><ol><li>增强正则，补齐加密HTTPS域名改写规则；</li><li>增加内存缓存，提升瓦片加载速度；</li><li>集成SW兜底拦截，解决漏改请求；</li><li>支持Docker一键部署，降低内网部署成本。</li></ol><h2 id="八、开源地址" tabindex="-1">八、开源地址 <a class="header-anchor" href="#八、开源地址" aria-label="Permalink to &quot;八、开源地址&quot;">​</a></h2><blockquote><p><strong>高德地图内网代理（Node.js）</strong></p><p>GitHub：<a href="https://github.com/akcshen/gaode-proxy.git" target="_blank" rel="noreferrer">https://github.com/akcshen/gaode-proxy.git</a></p><p>欢迎Star、提Issue、共同完善内网地图代理方案。</p></blockquote>`,64)])])}const k=a(s,[["render",r]]);export{g as __pageData,k as default};
